-- 병용금기 실데이터 시드 (급여/비급여 각 5000행, 총 1만행 추출)
-- ingredients: 914  products: 3433  interactions: 3786

-- RLS: 인증 없이도 조회 가능하도록 변경
DROP POLICY IF EXISTS "인증된 사용자만 제품 조회" ON products;
DROP POLICY IF EXISTS "인증된 사용자만 성분 조회" ON ingredients;
DROP POLICY IF EXISTS "인증된 사용자만 제품-성분 조회" ON product_ingredients;
DROP POLICY IF EXISTS "인증된 사용자만 상호작용 조회" ON ingredient_interactions;
DROP POLICY IF EXISTS "인증된 사용자만 환자 조회" ON patients;
DROP POLICY IF EXISTS "인증된 사용자만 환자 등록" ON patients;
DROP POLICY IF EXISTS "인증된 사용자만 환자 수정" ON patients;

CREATE POLICY "누구나 제품 조회" ON products FOR SELECT USING (true);
CREATE POLICY "누구나 성분 조회" ON ingredients FOR SELECT USING (true);
CREATE POLICY "누구나 제품-성분 조회" ON product_ingredients FOR SELECT USING (true);
CREATE POLICY "누구나 상호작용 조회" ON ingredient_interactions FOR SELECT USING (true);
CREATE POLICY "누구나 환자 조회" ON patients FOR SELECT USING (true);
CREATE POLICY "누구나 환자 등록" ON patients FOR INSERT WITH CHECK (true);
CREATE POLICY "누구나 환자 수정" ON patients FOR UPDATE USING (true);

DELETE FROM ingredient_interactions;
DELETE FROM product_ingredients;
DELETE FROM products;
DELETE FROM ingredients;

